"""Builds JSON and Markdown security reports from an AnalysisResult."""
from __future__ import annotations

import json
import re
from typing import Optional

from modules.ai_review import AIReviewResult
from modules.analyzer import AnalysisResult
from modules.vulnerability_checks import KIND_HEURISTIC, KIND_TOOL

DISCLAIMER = (
    "Automated review is not a full security audit. Tool findings come from static-analysis tools; "
    "heuristic warnings are pattern matches that may be false alarms; AI text is generated by a language "
    "model and may be wrong. Always review fixes yourself. Use only on code you are authorized to review."
)


def build_report(result: AnalysisResult, ai_review: Optional[AIReviewResult] = None) -> dict:
    """Return the report as a plain dictionary (ready for JSON)."""
    if ai_review is not None and ai_review.ok:
        ai_section = {
            "included": True,
            "label": "AI-generated, not verified by static analysis",
            "provider": ai_review.provider,
            "model": ai_review.model,
            "text": ai_review.text,
        }
    else:
        reason = ai_review.error if ai_review is not None else "AI review was not requested."
        ai_section = {"included": False, "reason": reason}

    return {
        "report_title": "AI Security Code Review Assistant - Security Report",
        "filename": result.filename,
        "language": result.language,
        "scan_date": result.scanned_at,
        "lines_analyzed": result.line_count,
        "tools_used": result.tools_used,
        "notes": result.notes,
        "summary": {
            "total_findings": result.total,
            "by_severity": result.severity_counts(),
            "tool_findings": sum(1 for f in result.findings if f.kind == KIND_TOOL),
            "heuristic_warnings": sum(1 for f in result.findings if f.kind == KIND_HEURISTIC),
        },
        "findings": [finding.to_dict() for finding in result.findings],
        "ai_review": ai_section,
        "disclaimer": DISCLAIMER,
    }


def report_to_json(report: dict) -> str:
    return json.dumps(report, indent=2, ensure_ascii=False)


def _fenced(text: str, language: str = "") -> str:
    """Wrap text in a Markdown code fence that is longer than any backtick run inside it."""
    longest = max((len(run) for run in re.findall(r"`+", text)), default=0)
    fence = "`" * max(3, longest + 1)
    return f"{fence}{language}\n{text}\n{fence}"


def report_to_markdown(report: dict) -> str:
    """Return a readable Markdown version of the report."""
    summary = report["summary"]
    lines = [
        f"# {report['report_title']}",
        "",
        f"- **File:** {report['filename']}",
        f"- **Language:** {report['language']}",
        f"- **Scan date:** {report['scan_date']}",
        f"- **Lines analyzed:** {report['lines_analyzed']}",
        f"- **Tools used:** {', '.join(report['tools_used'])}",
        "",
        "## Summary",
        "",
        f"- Total findings: **{summary['total_findings']}**"
        f" ({summary['tool_findings']} tool findings, {summary['heuristic_warnings']} heuristic warnings)",
    ]
    for severity, count in summary["by_severity"].items():
        lines.append(f"- {severity}: {count}")
    for note in report["notes"]:
        lines += ["", f"> Note: {note}"]

    lines += ["", "## Findings", ""]
    if not report["findings"]:
        lines.append("No issues were detected by the checks that ran. This does not prove the code is secure.")
    for number, finding in enumerate(report["findings"], start=1):
        line_text = finding["line"] if finding["line"] is not None else "not available"
        lines += [
            f"### {number}. {finding['title']}",
            "",
            f"- **Severity:** {finding['severity']}",
            f"- **Line:** {line_text}",
            f"- **Confidence:** {finding['confidence']}",
            f"- **Source:** {finding['source']} ({finding['kind']})",
            "",
            "**Vulnerable code:**",
            "",
            _fenced(finding["snippet"] or "(not available)"),
            "",
            f"**Why it is a risk:** {finding['why']}",
            "",
            f"**How an attacker might abuse it (explained for defense):** {finding['attack']}",
            "",
            f"**Recommended fix:** {finding['fix']}",
            "",
            "**Secure code example:**",
            "",
            _fenced(finding["secure_example"]),
            "",
        ]

    lines += ["## AI-generated review (unverified)", ""]
    ai = report["ai_review"]
    if ai["included"]:
        lines += [f"_Generated by {ai['provider']} ({ai['model']}). Not verified by static analysis._", "", ai["text"], ""]
    else:
        lines += [f"Not included: {ai['reason']}", ""]

    lines += ["## Disclaimer", "", report["disclaimer"], ""]
    return "\n".join(lines)
